 20	public class App {
 21	    private static Database database;
 22	    private static ReservationService reservationService;
 23	    private static ReportGenerator reportGenerator;
 24	    private static ObjectMapper objectMapper;
 25	
 26	    public static void main(String[] args) throws Exception {
 27	        initializeDatabase();
 28	        initializeServices();
 29	        setupApp();
 30	    }
 31	
 32	    private static void initializeDatabase() throws Exception {
 33	        String dbUrl = System.getenv("DB_URL");
 34	        String dbUser = System.getenv("DB_USER");
 35	        String dbPassword = System.getenv("DB_PASSWORD");
 36	
 37	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 38	            throw new RuntimeException("Missing database configuration");
 39	        }
 40	
 41	        database = new Database(dbUrl, dbUser, dbPassword);
 42	    }
 43	
 44	    private static void initializeServices() {
 45	        objectMapper = new ObjectMapper();
 46	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 47	
 48	        reservationService = new ReservationService(database);
 49	        reportGenerator = new ReportGenerator(database);
 50	    }
 51	
 52	    private static void setupApp() throws Exception {
 53	        int port = 7070;
 54	        if (System.getenv("PORT") != null) {
 55	            port = Integer.parseInt(System.getenv("PORT"));
 56	        }
 57	
 58	        Javalin app = Javalin.create();
 59	        app.start(port);
 60	
 61	        // GET /rooms
 62	        app.get("/rooms", ctx -> {
 63	            try {
 64	                List<Room> rooms = database.getAllRooms();
 65	                List<RoomResponse> responses = new ArrayList<>();
 66	
 67	                for (Room room : rooms) {
 68	                    RoomResponse response = new RoomResponse();
 69	                    response.number = room.getNumber();
 70	                    response.type = room.getType().getDisplayName();
 71	                    response.capacity = room.getCapacity();
 72	                    response.nightlyRate = room.getNightlyRate();
 73	                    responses.add(response);
 74	                }
 75	
 76	                ctx.json(responses);
 77	            } catch (Exception e) {
 78	                ctx.status(500);
 79	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
 80	            }
 81	        });
 82	
 83	        // POST /reservations
 84	        app.post("/reservations", ctx -> {
 85	            try {
 86	                CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
 87	
 88	                if (req.roomNumber == 0 || req.guestName == null || req.guestEmail == null ||
 89	                    req.guestCpf == null || req.checkIn == null || req.checkOut == null ||
 90	                    req.ratePlan == null) {
 91	                    ctx.status(400);
 92	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
 93	                    return;
 94	                }
 95	
 96	                LocalDate checkIn = LocalDate.parse(req.checkIn, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
 97	                LocalDate checkOut = LocalDate.parse(req.checkOut, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
 98	                RatePlan ratePlan = RatePlan.valueOf(req.ratePlan);
 99	
100	                Reservation reservation = reservationService.createReservation(
101	                    req.roomNumber, req.guestName, req.guestEmail, req.guestCpf,
102	                    checkIn, checkOut, req.guests, ratePlan
103	                );
104	
105	                ctx.status(201);
106	                ctx.json(toReservationResponse(reservation));
107	            } catch (ReservationService.RoomNotFoundException e) {
108	                ctx.status(404);
109	                ctx.json(new ErrorResponse(e.code, "Room not found"));
110	            } catch (ReservationService.CapacityExceededException e) {
111	                ctx.status(422);
112	                ctx.json(new ErrorResponse(e.code, "Capacity exceeded"));
113	            } catch (ReservationService.RoomUnavailableException e) {
114	                ctx.status(409);
115	                ctx.json(new ErrorResponse(e.code, "Room unavailable"));
116	            } catch (ReservationService.InvalidRequestException e) {
117	                ctx.status(400);
118	                ctx.json(new ErrorResponse(e.code, "Invalid request"));
119	            } catch (Exception e) {
120	                ctx.status(400);
121	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
122	            }
123	        });
124	
125	        // GET /reservations/{id}
126	        app.get("/reservations/{id}", ctx -> {
127	            try {
128	                long reservationId = Long.parseLong(ctx.pathParam("id"));
129	                Reservation reservation = reservationService.getReservation(reservationId);
130	                ctx.json(toReservationResponse(reservation));
131	            } catch (ReservationService.ReservationNotFoundException e) {
132	                ctx.status(404);
133	                ctx.json(new ErrorResponse(e.code, "Reservation not found"));
134	            } catch (Exception e) {
135	                ctx.status(400);
136	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
137	            }
138	        });
139	
140	        // POST /reservations/{id}/confirmation
141	        app.post("/reservations/{id}/confirmation", ctx -> {
142	            try {
143	                long reservationId = Long.parseLong(ctx.pathParam("id"));
144	                ConfirmationRequest req = ctx.bodyAsClass(ConfirmationRequest.class);
145	
146	                Reservation reservation = reservationService.confirmReservation(reservationId, req.amountPaid);
147	
148	                Room room = database.getRoomByNumber(reservation.getRoomNumber());
149	                String roomType = room.getType().getDisplayName();
150	
151	                String emailBody = DocumentGenerator.generateConfirmationEmail(reservation, roomType);
152	                database.saveMessage(MessageChannel.EMAIL, reservation.getGuestEmail(),
153	                    "Reserva confirmada - Pousada Maré Alta", emailBody);
154	
155	                ctx.json(toReservationResponse(reservation));
156	            } catch (ReservationService.ReservationNotFoundException e) {
157	                ctx.status(404);
158	                ctx.json(new ErrorResponse(e.code, "Reservation not found"));
159	            } catch (ReservationService.OperationNotAllowedException e) {
160	                ctx.status(409);
161	                ctx.json(new ErrorResponse(e.code, "Operation not allowed"));
162	            } catch (Exception e) {
163	                ctx.status(400);
164	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
165	            }
166	        });
167	
168	        // POST /reservations/{id}/cancellation
169	        app.post("/reservations/{id}/cancellation", ctx -> {
170	            try {
171	                long reservationId = Long.parseLong(ctx.pathParam("id"));
172	                Reservation reservation = reservationService.cancelReservation(reservationId);
173	                ctx.json(toReservationResponse(reservation));
174	            } catch (ReservationService.ReservationNotFoundException e) {
175	                ctx.status(404);
176	                ctx.json(new ErrorResponse(e.code, "Reservation not found"));
177	            } catch (ReservationService.OperationNotAllowedException e) {
178	                ctx.status(409);
179	                ctx.json(new ErrorResponse(e.code, "Operation not allowed"));
180	            } catch (Exception e) {
181	                ctx.status(400);
182	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
183	            }
184	        });
185	
186	        // POST /reservations/{id}/check-in
187	        app.post("/reservations/{id}/check-in", ctx -> {
188	            try {
189	                long reservationId = Long.parseLong(ctx.pathParam("id"));
190	                Reservation reservation = reservationService.checkInReservation(reservationId);
191	                ctx.json(toReservationResponse(reservation));
192	            } catch (ReservationService.ReservationNotFoundException e) {
193	                ctx.status(404);
194	                ctx.json(new ErrorResponse(e.code, "Reservation not found"));
195	            } catch (ReservationService.OperationNotAllowedException e) {
196	                ctx.status(409);
197	                ctx.json(new ErrorResponse(e.code, "Operation not allowed"));
198	            } catch (Exception e) {
199	                ctx.status(400);
200	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
201	            }
202	        });
203	
204	        // POST /reservations/{id}/check-out
205	        app.post("/reservations/{id}/check-out", ctx -> {
206	            try {
207	                long reservationId = Long.parseLong(ctx.pathParam("id"));
208	                Reservation reservation = reservationService.checkOutReservation(reservationId);
209	
210	                Room room = database.getRoomByNumber(reservation.getRoomNumber());
211	                String roomType = room.getType().getDisplayName();
212	
213	                DocumentResponse doc = new DocumentResponse();
214	                doc.reservationId = reservation.getId();
215	                doc.guestName = reservation.getGuestName();
216	                doc.guestCpf = reservation.getGuestCpf();
217	                doc.roomNumber = reservation.getRoomNumber();
218	                doc.roomType = roomType;
219	                doc.checkIn = reservation.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
220	                doc.checkOut = reservation.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
221	                doc.nights = reservation.getNights();
222	                doc.subtotal = reservation.getSubtotal();
223	                doc.discount = reservation.getDiscount();
224	                doc.total = reservation.getTotal();
225	
226	                ctx.json(doc);
227	            } catch (ReservationService.ReservationNotFoundException e) {
228	                ctx.status(404);
229	                ctx.json(new ErrorResponse(e.code, "Reservation not found"));
230	            } catch (ReservationService.OperationNotAllowedException e) {
231	                ctx.status(409);
232	                ctx.json(new ErrorResponse(e.code, "Operation not allowed"));
233	            } catch (Exception e) {
234	                ctx.status(400);
235	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
236	            }
237	        });
238	
239	        // GET /reservations/{id}/document
240	        app.get("/reservations/{id}/document", ctx -> {
241	            try {
242	                long reservationId = Long.parseLong(ctx.pathParam("id"));
243	                Reservation reservation = reservationService.getReservation(reservationId);
244	
245	                if (reservation.getStatus() == ReservationStatus.PENDING) {
246	                    ctx.status(409);
247	                    ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document not available for pending reservations"));
248	                    return;
249	                }
250	
251	                Room room = database.getRoomByNumber(reservation.getRoomNumber());
252	                String roomType = room.getType().getDisplayName();
253	
254	                DocumentResponse doc = new DocumentResponse();
255	                doc.reservationId = reservation.getId();
256	                doc.guestName = reservation.getGuestName();
257	                doc.guestCpf = reservation.getGuestCpf();
258	                doc.roomNumber = reservation.getRoomNumber();
259	                doc.roomType = roomType;
260	                doc.checkIn = reservation.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
261	                doc.checkOut = reservation.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
262	                doc.nights = reservation.getNights();
263	                doc.subtotal = reservation.getSubtotal();
264	                doc.discount = reservation.getDiscount();
265	                doc.total = reservation.getTotal();
266	
267	                ctx.json(doc);
268	            } catch (ReservationService.ReservationNotFoundException e) {
269	                ctx.status(404);
270	                ctx.json(new ErrorResponse(e.code, "Reservation not found"));
271	            } catch (Exception e) {
272	                ctx.status(400);
273	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
274	            }
275	        });
276	
277	        // GET /messages
278	        app.get("/messages", ctx -> {
279	            try {
280	                List<Message> messages = database.getAllMessages();
281	                List<MessageResponse> responses = new ArrayList<>();
282	
283	                for (Message message : messages) {
284	                    MessageResponse response = new MessageResponse();
285	                    response.id = message.getId();
286	                    response.channel = message.getChannel().name();
287	                    response.to = message.getTo();
288	                    response.subject = message.getSubject();
289	                    response.body = message.getBody();
290	                    responses.add(response);
291	                }
292	
293	                ctx.json(responses);
294	            } catch (Exception e) {
295	                ctx.status(500);
296	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
297	            }
298	        });
299	
300	        // GET /reports/occupancy
301	        app.get("/reports/occupancy", ctx -> {
302	            try {
303	                String dateParam = ctx.queryParam("date");
304	                if (dateParam == null) {
305	                    ctx.status(400);
306	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
307	                    return;
308	                }
309	
310	                LocalDate date = LocalDate.parse(dateParam, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
311	                String report = reportGenerator.generateOccupancyReport(date);
312	
313	                ctx.contentType("text/csv; charset=utf-8");
314	                ctx.result(report);
315	            } catch (Exception e) {
316	                ctx.status(400);
317	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
318	            }
319	        });
320	
321	        // GET /reports/revenue
322	        app.get("/reports/revenue", ctx -> {
323	            try {
324	                String monthParam = ctx.queryParam("month");
325	                if (monthParam == null) {
326	                    ctx.status(400);
327	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
328	                    return;
329	                }
330	
331	                YearMonth month = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
332	                String report = reportGenerator.generateRevenueReport(month);
333	
334	                ctx.contentType("text/csv; charset=utf-8");
335	                ctx.result(report);
336	            } catch (Exception e) {
337	                ctx.status(400);
338	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
339	            }
340	        });
341	
342	        // GET /reports/tourism-tax
343	        app.get("/reports/tourism-tax", ctx -> {
344	            try {
345	                String monthParam = ctx.queryParam("month");
346	                if (monthParam == null) {
347	                    ctx.status(400);
348	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
349	                    return;
350	                }
351	
352	                YearMonth month = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
353	                String report = reportGenerator.generateTourismTaxReport(month);
354	
355	                ctx.contentType("text/csv; charset=utf-8");
356	                ctx.result(report);
357	            } catch (Exception e) {
358	                ctx.status(400);
359	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
360	            }
361	        });
362	
363	        // GET /reports/rate-plans
364	        app.get("/reports/rate-plans", ctx -> {
365	            try {
366	                String monthParam = ctx.queryParam("month");
367	                if (monthParam == null) {
368	                    ctx.status(400);
369	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
370	                    return;
371	                }
372	
373	                YearMonth month = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
374	                String report = reportGenerator.generateRatePlanReport(month);
375	
376	                ctx.contentType("text/csv; charset=utf-8");
377	                ctx.result(report);
378	            } catch (Exception e) {
379	                ctx.status(400);
380	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
381	            }
382	        });
383	    }
384	
385	    private static ReservationResponse toReservationResponse(Reservation reservation) {
386	        ReservationResponse response = new ReservationResponse();
387	        response.id = reservation.getId();
388	        response.roomNumber = reservation.getRoomNumber();
389	        response.guestName = reservation.getGuestName();
390	        response.guestEmail = reservation.getGuestEmail();
391	        response.guestCpf = reservation.getGuestCpf();
392	        response.checkIn = reservation.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
393	        response.checkOut = reservation.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
394	        response.guests = reservation.getGuests();
395	        response.ratePlan = reservation.getRatePlan().name();
396	        response.nights = reservation.getNights();
397	        response.subtotal = reservation.getSubtotal();
398	        response.discount = reservation.getDiscount();
399	        response.total = reservation.getTotal();
400	        response.status = reservation.getStatus().name();
401	        response.amountPaid = reservation.getAmountPaid();
402	        response.refund = reservation.getRefund();
403	        return response;
404	    }
405	}

