 60	
 61	public class ReportGenerator {
 62	    private final Database database;
 63	
 64	    public ReportGenerator(Database database) {
 65	        this.database = database;
 66	    }
 67	
 68	    public String generateOccupancyReport(LocalDate date) throws Exception {
 69	        List<Reservation> reservations = database.getReservationsForOccupancy(date);
 70	
 71	        StringBuilder sb = new StringBuilder();
 72	        sb.append("Pousada Maré Alta,occupancy,").append(date.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append("\n");
 73	        sb.append("room,type,reservation,check_in,check_out\n");
 74	
 75	        for (Reservation res : reservations) {
 76	            String roomType = database.getRoomByNumber(res.getRoomNumber()).getType().name();
 77	            sb.append(res.getRoomNumber()).append(",")
 78	              .append(roomType).append(",")
 79	              .append(res.getId()).append(",")
 80	              .append(res.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
 81	              .append(res.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append("\n");
 82	        }
 83	
 84	        sb.append("total,").append(reservations.size()).append("/5\n");
 85	
 86	        return sb.toString();
 87	    }
 88	
 89	    public String generateRevenueReport(YearMonth month) throws Exception {
 90	        List<Reservation> reservations = database.getReservationsForMonth(month.getYear(), month.getMonthValue());
 91	
 92	        StringBuilder sb = new StringBuilder();
 93	        sb.append("Pousada Maré Alta,revenue,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
 94	        sb.append("reservation,room,check_in,check_out,status,amount\n");
 95	
 96	        BigDecimal totalAmount = BigDecimal.ZERO;
 97	
 98	        for (Reservation res : reservations) {
 99	            BigDecimal amountForPousada = res.getAmountPaid();
100	            if (res.getRefund() != null && res.getRefund().compareTo(BigDecimal.ZERO) > 0) {
101	                amountForPousada = amountForPousada.subtract(res.getRefund());
102	            }
103	
104	            sb.append(res.getId()).append(",")
105	              .append(res.getRoomNumber()).append(",")
106	              .append(res.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
107	              .append(res.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
108	              .append(res.getStatus().name()).append(",")
109	              .append(formatDecimal(amountForPousada)).append("\n");
110	
111	            totalAmount = totalAmount.add(amountForPousada);
112	        }
113	
114	        sb.append("total,").append(formatDecimal(totalAmount)).append("\n");
115	
116	        return sb.toString();
117	    }
118	
119	    public String generateTourismTaxReport(YearMonth month) throws Exception {
120	        List<Reservation> reservations = database.getReservationsForMonth(month.getYear(), month.getMonthValue());
121	
122	        StringBuilder sb = new StringBuilder();
123	        sb.append("Pousada Maré Alta,tourism-tax,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
124	        sb.append("reservation,room,check_in,check_out,guests,nights,tax\n");
125	
126	        BigDecimal tourismTaxRate = new BigDecimal("4.50");
127	        BigDecimal totalTax = BigDecimal.ZERO;
128	
129	        for (Reservation res : reservations) {
130	            BigDecimal tax = calculateTourismTax(res.getGuests(), res.getNights(), tourismTaxRate);
131	
132	            sb.append(res.getId()).append(",")
133	              .append(res.getRoomNumber()).append(",")
134	              .append(res.getCheckIn().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
135	              .append(res.getCheckOut().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))).append(",")
136	              .append(res.getGuests()).append(",")
137	              .append(res.getNights()).append(",")
138	              .append(formatDecimal(tax)).append("\n");
139	
140	            totalTax = totalTax.add(tax);
141	        }
142	
143	        sb.append("total,").append(formatDecimal(totalTax)).append("\n");
144	
145	        return sb.toString();
146	    }
147	
148	    public String generateRatePlanReport(YearMonth month) throws Exception {
149	        List<Reservation> reservations = database.getReservationsForMonth(month.getYear(), month.getMonthValue());
150	
151	        StringBuilder sb = new StringBuilder();
152	        sb.append("Pousada Maré Alta,rate-plans,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
153	        sb.append("rate_plan,reservations,amount\n");
154	
155	        int standardCount = 0;
156	        int nonRefundableCount = 0;
157	        BigDecimal standardAmount = BigDecimal.ZERO;
158	        BigDecimal nonRefundableAmount = BigDecimal.ZERO;
159	
160	        for (Reservation res : reservations) {
161	            BigDecimal amountForPousada = res.getAmountPaid();
162	            if (res.getRefund() != null && res.getRefund().compareTo(BigDecimal.ZERO) > 0) {
163	                amountForPousada = amountForPousada.subtract(res.getRefund());
164	            }
165	
166	            if (res.getRatePlan() == RatePlan.STANDARD) {
167	                standardCount++;
168	                standardAmount = standardAmount.add(amountForPousada);
169	            } else {
170	                nonRefundableCount++;
171	                nonRefundableAmount = nonRefundableAmount.add(amountForPousada);
172	            }
173	        }
174	
175	        sb.append("STANDARD,").append(standardCount).append(",").append(formatDecimal(standardAmount)).append("\n");
176	        sb.append("NON_REFUNDABLE,").append(nonRefundableCount).append(",").append(formatDecimal(nonRefundableAmount)).append("\n");
177	
178	        BigDecimal totalAmount = standardAmount.add(nonRefundableAmount);
179	        int totalCount = standardCount + nonRefundableCount;
180	        sb.append("total,").append(totalCount).append(",").append(formatDecimal(totalAmount)).append("\n");
181	
182	        return sb.toString();
183	    }
184	
185	    private BigDecimal calculateTourismTax(int guests, int nights, BigDecimal rate) {
186	        BigDecimal taxValue = new BigDecimal(guests).multiply(new BigDecimal(nights)).multiply(rate);
187	        return taxValue.setScale(2, java.math.RoundingMode.HALF_EVEN);
188	    }
189	
190	    private String formatDecimal(BigDecimal value) {
191	        return String.format("%.2f", value);
192	    }
193	}
