211	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
212	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
213	                                        int guests, RatePlan ratePlan) throws Exception {
214	        Room room = database.getRoomByNumber(roomNumber);
215	        if (room == null) {
216	            throw new RoomNotFoundException("ROOM_NOT_FOUND");
217	        }
218	
219	        if (guests < 1) {
220	            throw new InvalidRequestException("INVALID_REQUEST");
221	        }
222	
223	        if (guests > room.getCapacity()) {
224	            throw new CapacityExceededException("CAPACITY_EXCEEDED");
225	        }
226	
227	        if (checkIn.isAfter(checkOut) || checkIn.isEqual(checkOut)) {
228	            throw new InvalidRequestException("INVALID_REQUEST");
229	        }
230	
231	        List<Reservation> conflicts = database.getReservationsByRoomAndDates(roomNumber, checkIn, checkOut);
232	        if (!conflicts.isEmpty()) {
233	            throw new RoomUnavailableException("ROOM_UNAVAILABLE");
234	        }
235	
236	        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
237	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
238	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan.name());
239	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
240	
241	        Reservation reservation = new Reservation();
242	        reservation.setRoomNumber(roomNumber);
243	        reservation.setGuestName(guestName);
244	        reservation.setGuestEmail(guestEmail);
245	        reservation.setGuestCpf(guestCpf);
246	        reservation.setCheckIn(checkIn);
247	        reservation.setCheckOut(checkOut);
248	        reservation.setGuests(guests);
249	        reservation.setRatePlan(ratePlan);
250	        reservation.setNights(nights);
251	        reservation.setSubtotal(subtotal);
252	        reservation.setDiscount(discount);
253	        reservation.setTotal(total);
254	
255	        return database.createReservation(reservation);
256	    }
257	
258	    public Reservation getReservation(long id) throws Exception {
259	        Reservation reservation = database.getReservationById(id);
260	        if (reservation == null) {
261	            throw new ReservationNotFoundException("RESERVATION_NOT_FOUND");
262	        }
263	        return reservation;
264	    }
265	
266	    public Reservation confirmReservation(long id, BigDecimal amountPaid) throws Exception {
267	        Reservation reservation = getReservation(id);
268	
269	        if (reservation.getStatus() != ReservationStatus.PENDING) {
270	            throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
271	        }
272	
273	        database.updateReservationAfterConfirmation(id, amountPaid);
274	        reservation.setStatus(ReservationStatus.CONFIRMED);
275	        reservation.setAmountPaid(amountPaid);
276	
277	        return reservation;
278	    }
279	
280	    public Reservation checkInReservation(long id) throws Exception {
281	        Reservation reservation = getReservation(id);
282	
283	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
284	            throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
285	        }
286	
287	        database.updateReservationStatus(id, ReservationStatus.CHECKED_IN);
288	        reservation.setStatus(ReservationStatus.CHECKED_IN);
289	
290	        return reservation;
291	    }
292	
293	    public Reservation checkOutReservation(long id) throws Exception {
294	        Reservation reservation = getReservation(id);
295	
296	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
297	            throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
298	        }
299	
300	        database.updateReservationStatus(id, ReservationStatus.CHECKED_OUT);
301	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
302	
303	        return reservation;
304	    }
305	
306	    public Reservation cancelReservation(long id) throws Exception {
307	        Reservation reservation = getReservation(id);
308	
309	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
310	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
311	            reservation.getStatus() == ReservationStatus.CANCELLED) {
312	            throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
313	        }
314	
315	        BigDecimal refund = BigDecimal.ZERO;
316	        if (reservation.getStatus() == ReservationStatus.CONFIRMED &&
317	            reservation.getRatePlan() == RatePlan.STANDARD) {
318	            refund = reservation.getAmountPaid();
319	        }
320	
321	        database.updateReservationAfterCancellation(id, refund);
322	        reservation.setStatus(ReservationStatus.CANCELLED);
323	        reservation.setRefund(refund);
324	
325	        return reservation;
326	    }
