382	public class PriceCalculator {
383	    private static final BigDecimal PEAK_SEASON_INCREASE = new BigDecimal("0.20");
384	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
385	
386	    public static boolean isPeakSeason(LocalDate date) {
387	        int month = date.getMonthValue();
388	        int day = date.getDayOfMonth();
389	
390	        if (month >= 12 && day >= 15) return true;
391	        if (month <= 2) return true;
392	        if (month == 7) return true;
393	
394	        return false;
395	    }
396	
397	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
398	        if (isPeakSeason(date)) {
399	            BigDecimal increase = baseRate.multiply(PEAK_SEASON_INCREASE);
400	            return round(baseRate.add(increase));
401	        }
402	        return baseRate;
403	    }
404	
405	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
406	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
407	    }
408	
409	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
410	        int nights = calculateNights(checkIn, checkOut);
411	        BigDecimal subtotal = BigDecimal.ZERO;
412	
413	        LocalDate current = checkIn;
414	        while (current.isBefore(checkOut)) {
415	            BigDecimal nightlyPrice = calculateNightlyPrice(baseRate, current);
416	            subtotal = subtotal.add(nightlyPrice);
417	            current = current.plusDays(1);
418	        }
419	
420	        return round(subtotal);
421	    }
422	
423	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
424	        if ("NON_REFUNDABLE".equals(ratePlan)) {
425	            BigDecimal discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT);
426	            return round(discount);
427	        }
428	        return BigDecimal.ZERO;
429	    }
430	
431	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
432	        return round(subtotal.subtract(discount));
433	    }
434	
435	    private static BigDecimal round(BigDecimal value) {
436	        return value.setScale(2, RoundingMode.HALF_EVEN);
437	    }
