237	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
238	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan.name());
239	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
240	
