 12	
 13	public class Database {
 14	    private final HikariDataSource dataSource;
 15	
 16	    public Database(String dbUrl, String dbUser, String dbPassword) throws SQLException {
 17	        HikariConfig config = new HikariConfig();
 18	        config.setJdbcUrl(dbUrl);
 19	        config.setUsername(dbUser);
 20	        config.setPassword(dbPassword);
 21	        config.setMaximumPoolSize(10);
 22	
 23	        this.dataSource = new HikariDataSource(config);
 24	        initializeDatabase();
 25	    }
 26	
 27	    private void initializeDatabase() throws SQLException {
 28	        try (Connection conn = dataSource.getConnection()) {
 29	            createTablesIfNeeded(conn);
 30	            insertRoomsIfNeeded(conn);
 31	        }
 32	    }
 33	
 34	    private void createTablesIfNeeded(Connection conn) throws SQLException {
 35	        String createRoomsTable = """
 36	            CREATE TABLE IF NOT EXISTS rooms (
 37	                number INTEGER PRIMARY KEY,
 38	                type VARCHAR(50) NOT NULL,
 39	                capacity INTEGER NOT NULL,
 40	                nightly_rate NUMERIC(10, 2) NOT NULL
 41	            )
 42	            """;
 43	
 44	        String createReservationsTable = """
 45	            CREATE TABLE IF NOT EXISTS reservations (
 46	                id BIGSERIAL PRIMARY KEY,
 47	                room_number INTEGER NOT NULL REFERENCES rooms(number),
 48	                guest_name VARCHAR(255) NOT NULL,
 49	                guest_email VARCHAR(255) NOT NULL,
 50	                guest_cpf VARCHAR(20) NOT NULL,
 51	                check_in DATE NOT NULL,
 52	                check_out DATE NOT NULL,
 53	                guests INTEGER NOT NULL,
 54	                rate_plan VARCHAR(50) NOT NULL,
 55	                nights INTEGER NOT NULL,
 56	                subtotal NUMERIC(10, 2) NOT NULL,
 57	                discount NUMERIC(10, 2) NOT NULL,
 58	                total NUMERIC(10, 2) NOT NULL,
 59	                status VARCHAR(50) NOT NULL,
 60	                amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 61	                refund NUMERIC(10, 2),
 62	                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 63	            )
 64	            """;
 65	
 66	        String createMessagesTable = """
 67	            CREATE TABLE IF NOT EXISTS messages (
 68	                id BIGSERIAL PRIMARY KEY,
 69	                channel VARCHAR(50) NOT NULL,
 70	                to_address VARCHAR(255) NOT NULL,
 71	                subject VARCHAR(255) NOT NULL,
 72	                body TEXT NOT NULL,
 73	                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 74	            )
 75	            """;
 76	
 77	        try (Statement stmt = conn.createStatement()) {
 78	            stmt.execute(createRoomsTable);
 79	            stmt.execute(createReservationsTable);
 80	            stmt.execute(createMessagesTable);
 81	        }
 82	    }
 83	
 84	    private void insertRoomsIfNeeded(Connection conn) throws SQLException {
 85	        String checkQuery = "SELECT COUNT(*) FROM rooms";
 86	        try (Statement stmt = conn.createStatement()) {
 87	            ResultSet rs = stmt.executeQuery(checkQuery);
 88	            rs.next();
 89	            if (rs.getInt(1) == 0) {
 90	                insertDefaultRooms(conn);
 91	            }
 92	        }
 93	    }
