 95	    private void insertDefaultRooms(Connection conn) throws SQLException {
 96	        String insertQuery = "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?)";
 97	        try (PreparedStatement stmt = conn.prepareStatement(insertQuery)) {
 98	            stmt.setInt(1, 101);
