103	
104	            stmt.setInt(1, 102);
105	            stmt.setString(2, "STANDARD");
106	            stmt.setInt(3, 2);
107	            stmt.setBigDecimal(4, new BigDecimal("249.90"));
108	            stmt.addBatch();
109	
110	            stmt.setInt(1, 201);
111	            stmt.setString(2, "DELUXE");
