323	            ResultSet rs = stmt.executeQuery(query);
324	            while (rs.next()) {
325	                messages.add(new Message(
326	                    rs.getLong("id"),
327	                    MessageChannel.valueOf(rs.getString("channel")),
328	                    rs.getString("to_address"),
329	                    rs.getString("subject"),
330	                    rs.getString("body")
331	                ));
332	            }
333	        }
334	
335	        return messages;
336	    }
337	
338	    public List<Reservation> getReservationsForOccupancy(LocalDate date) throws SQLException {
339	        String query = """
340	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
341	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
342	            FROM reservations
343	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
344	            AND check_in <= ? AND check_out > ?
345	            ORDER BY room_number
346	            """;
347	
348	        List<Reservation> reservations = new ArrayList<>();
349	
350	        try (Connection conn = dataSource.getConnection();
351	             PreparedStatement stmt = conn.prepareStatement(query)) {
352	            stmt.setDate(1, Date.valueOf(date));
353	            stmt.setDate(2, Date.valueOf(date));
354	
355	            ResultSet rs = stmt.executeQuery();
356	            while (rs.next()) {
357	                reservations.add(mapResultSetToReservation(rs));
358	            }
359	        }
360	
361	        return reservations;
362	    }
363	
364	    public List<Reservation> getReservationsForMonth(int year, int month) throws SQLException {
365	        LocalDate startDate = LocalDate.of(year, month, 1);
366	        LocalDate endDate = startDate.plusMonths(1);
367	
368	        String query = """
369	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
370	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
371	            FROM reservations
372	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
373	            AND amount_paid > 0
374	            AND check_in >= ? AND check_in < ?
375	            ORDER BY check_in, id
376	            """;
377	
378	        List<Reservation> reservations = new ArrayList<>();
379	
380	        try (Connection conn = dataSource.getConnection();
381	             PreparedStatement stmt = conn.prepareStatement(query)) {
382	            stmt.setDate(1, Date.valueOf(startDate));
383	            stmt.setDate(2, Date.valueOf(endDate));
384	
385	            ResultSet rs = stmt.executeQuery();
386	            while (rs.next()) {
387	                reservations.add(mapResultSetToReservation(rs));
388	            }
389	        }
390	
391	        return reservations;
392	    }
393	
394	    private Reservation mapResultSetToReservation(ResultSet rs) throws SQLException {
395	        return new Reservation(
396	            rs.getLong("id"),
397	            rs.getInt("room_number"),
398	            rs.getString("guest_name"),
399	            rs.getString("guest_email"),
400	            rs.getString("guest_cpf"),
401	            rs.getDate("check_in").toLocalDate(),
402	            rs.getDate("check_out").toLocalDate(),
403	            rs.getInt("guests"),
404	            RatePlan.valueOf(rs.getString("rate_plan")),
405	            rs.getInt("nights"),
406	            rs.getBigDecimal("subtotal"),
407	            rs.getBigDecimal("discount"),
408	            rs.getBigDecimal("total"),
409	            ReservationStatus.valueOf(rs.getString("status")),
410	            rs.getBigDecimal("amount_paid"),
411	            rs.getBigDecimal("refund")
412	        );
413	    }
414	
415	    public void close() throws SQLException {
416	        if (dataSource != null && !dataSource.isClosed()) {
417	            dataSource.close();
418	        }
419	    }
420	}

